Definition iarm_1RB1LC_1LA1RA_1LB0RD_0LC1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_1LA1RA_1LB0RD_0LC1RD
  | 0, 1 => iarm0_1_1RB1LC_1LA1RA_1LB0RD_0LC1RD
  | 1, 0 => iarm1_0_1RB1LC_1LA1RA_1LB0RD_0LC1RD
  | 1, 1 => iarm1_1_1RB1LC_1LA1RA_1LB0RD_0LC1RD
  | 2, 0 => iarm2_0_1RB1LC_1LA1RA_1LB0RD_0LC1RD
  | 2, 1 => iarm2_1_1RB1LC_1LA1RA_1LB0RD_0LC1RD
  | _, _ => iarm0_0_1RB1LC_1LA1RA_1LB0RD_0LC1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

