    { eapply arm_sound; [exact rules_sound_1RB1LC_1LA1RA_1LB0RD_0LC1RD | exact ok_iarm2_0_1RB1LC_1LA1RA_1LB0RD_0LC1RD]. }
    destruct r as [|r].
