Definition iarm_1RB1LC_1RC1RA_0LA0LD_0RB1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_1RC1RA_0LA0LD_0RB1LD
  | 0, 1 => iarm0_1_1RB1LC_1RC1RA_0LA0LD_0RB1LD
  | 1, 0 => iarm1_0_1RB1LC_1RC1RA_0LA0LD_0RB1LD
  | 1, 1 => iarm1_1_1RB1LC_1RC1RA_0LA0LD_0RB1LD
  | _, _ => iarm0_0_1RB1LC_1RC1RA_0LA0LD_0RB1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

