Import LadderCheckNestPvTr.
Import ListNotations.

Definition mk_1RB1LD_0LC1RB_1LA0RB_1RC1LC (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1LD_0LC1RB_1LA0RB_1RC1LC.

(** 1RB1LD_0LC1RB_1LA0RB_1RC1LC *)
Definition tm_1RB1LD_0LC1RB_1LA0RB_1RC1LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S0 DL StC
  | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StA
  | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DR StC
  | StD, S1 => mk S1 DL StC
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1LD_0LC1RB_1LA0RB_1RC1LC : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1LD_0LC1RB_1LA0RB_1RC1LC pins_1RB1LD_0LC1RB_1LA0RB_1RC1LC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LD_0LC1RB_1LA0RB_1RC1LC : Fam := mkFam 2 [[S1;S1;S1];[S1;S1;S0]] [] [[S0;S1];[S1];[]] Binary 1 [mkFill 1 [] 0 [1] 2;mkFill 0 [] 0 [] 0;mkFill 0 [] 0 [] 1] StC S1 true [].
Local Notation FAM := fam_1RB1LD_0LC1RB_1LA0RB_1RC1LC.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LD_0LC1RB_1LA0RB_1RC1LC : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [S1;S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_1RB1LD_0LC1RB_1LA0RB_1RC1LC.

Definition rules_1RB1LD_0LC1RB_1LA0RB_1RC1LC : list LRule := map fst lad.
Local Notation rules := rules_1RB1LD_0LC1RB_1LA0RB_1RC1LC.

Lemma ladder_ok_1RB1LD_0LC1RB_1LA0RB_1RC1LC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LD_0LC1RB_1LA0RB_1RC1LC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LD_0LC1RB_1LA0RB_1RC1LC. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* C[1] L<1^3+y0> R<>  ==>  C[1] L<1^2 0^1 1^y0> R<>   [10 steps] *)
Definition arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC : LRule :=
  mkLRule (mkC StC (mkS [S1;S1;S1] [S1] 1 0 []) S1 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S1;S1;S0] [S1] 1 0 []) S1 (mkS [S0] [] 0 0 [])) 0 10.
Definition ch_arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC : list rstep := [RB (SWinR 10)].
Lemma ok_arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC :
  check_arm tm true true rules arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC ch_arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC : RuleSound tm true true arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC.
Proof. eapply arm_sound; [exact rules_sound_1RB1LD_0LC1RB_1LA0RB_1RC1LC | exact ok_arm14_1RB1LD_0LC1RB_1LA0RB_1RC1LC]. Qed.

