  match r, ph with
  | 1, 0 => farm1_0_1RB1LD_1RC0RB_1LA1LA_0LD0RC
  | 1, 1 => farm1_1_1RB1LD_1RC0RB_1LA1LA_0LD0RC
  | _, _ => farm1_0_1RB1LD_1RC0RB_1LA1LA_0LD0RC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LD_1RC0RB_1LA1LA_0LD0RC (r ph : nat) : nat :=
