(* arm11: NO KERNEL CHAIN -- no chain found *)
(* arm44: NO KERNEL CHAIN -- no chain found *)
(* arm24: NO KERNEL CHAIN -- no chain found *)
(* arm32: NO KERNEL CHAIN -- no chain found *)
(* arm43: NO KERNEL CHAIN -- no chain found *)
(* arm16: NO KERNEL CHAIN -- no chain found *)
(** ** What this board establishes

    4 of 10 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 10 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    0 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1LD_1RC1RA_0LA1RA_0RB0LD : list (LRule * list rstep) :=
  [].
Definition nrules_1RB1LD_1RC1RA_0LA1RA_0RB0LD : list LRule := map fst nlad_1RB1LD_1RC1RA_0LA1RA_0RB0LD.
Local Notation nrules := nrules_1RB1LD_1RC1RA_0LA1RA_0RB0LD.

Lemma nladder_ok_1RB1LD_1RC1RA_0LA1RA_0RB0LD : check_ladder tm [] nlad_1RB1LD_1RC1RA_0LA1RA_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1LD_1RC1RA_0LA1RA_0RB0LD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1LD_1RC1RA_0LA1RA_0RB0LD. Qed.

Definition iarm0_0_1RB1LD_1RC1RA_0LA1RA_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1LD_1RC1RA_0LA1RA_0RB0LD : list nseg :=
  [NCh [RB (SWin 4)]].
Lemma ok_iarm0_0_1RB1LD_1RC1RA_0LA1RA_0RB0LD :
  check_narm tm true false nrules iarm0_0_1RB1LD_1RC1RA_0LA1RA_0RB0LD ch_iarm0_0_1RB1LD_1RC1RA_0LA1RA_0RB0LD = true.
