Definition iarm0_1_1RB1LD_1RC1RA_0LA1RA_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1;S0] 1 0 [S0;S0]))
