  check_narm tm true false nrules iarm0_1_1RB1LD_1RC1RA_0LA1RA_0RB0LD ch_iarm0_1_1RB1LD_1RC1RA_0LA1RA_0RB0LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1LD_1RC1RA_0LA1RA_0RB0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1;S0] 1 0 [S0;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S0;S0;S0;S1])) 0 1.
