Lemma bootl_1RB1LD_1RC1RA_0LA1RA_0RB0LD :
  stepn tm 15 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 15 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB1LD_1RC1RA_0LA1RA_0RB0LD : NeverQuasiHaltsTr tm_1RB1LD_1RC1RA_0LA1RA_0RB0LD.
Proof.
  eapply (boardN_neverqhtr tm_1RB1LD_1RC1RA_0LA1RA_0RB0LD pins_1RB1LD_1RC1RA_0LA1RA_0RB0LD FAM 1
                           iarm_1RB1LD_1RC1RA_0LA1RA_0RB0LD 1 1
                           farm_1RB1LD_1RC1RA_0LA1RA_0RB0LD 1 1
                           fm1_1RB1LD_1RC1RA_0LA1RA_0RB0LD fm2_1RB1LD_1RC1RA_0LA1RA_0RB0LD 0
                           nrules vsegs_1RB1LD_1RC1RA_0LA1RA_0RB0LD vis_1RB1LD_1RC1RA_0LA1RA_0RB0LD
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LD_1RC1RA_0LA1RA_0RB0LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
